const t=[{id:"shock-states-001",topicId:"shock-states",question:"От какого английского слова происходит термин «шок» и что оно означает?",options:["От shock — «удар, толчок»","От shake — «сотрясение, дрожь»","От shortage — «нехватка, недостаток»","От shut — «закрытие, прекращение»"],correctIndex:0,explanation:"Термин «шок» происходит от английского слова shock, что означает «удар, толчок».",difficulty:"easy",tags:["терминология","определение"]},{id:"shock-states-002",topicId:"shock-states",question:"Что такое шоковые состояния?",options:["Кратковременная потеря сознания вследствие спазма сосудов головного мозга","Тяжёлые, угрожающие жизни патологические реакции организма в ответ на действие сильных повреждающих факторов","Хроническое снижение артериального давления, развивающееся годами","Защитно-приспособительная реакция организма на повреждение тканей"],correctIndex:1,explanation:"Шоковые состояния — это тяжёлые, угрожающие жизни патологические реакции организма, возникающие в ответ на действие сильных повреждающих факторов.",difficulty:"easy",tags:["определение"]},{id:"shock-states-003",topicId:"shock-states",question:"Нарушение каких процессов сопровождает шоковые состояния?",options:["Только кровообращения и дыхания","Только нервной регуляции и обмена веществ","Кровообращения, дыхания, нервной регуляции и обмена веществ","Только водно-электролитного баланса"],correctIndex:2,explanation:"Шоковые состояния сопровождаются резким нарушением кровообращения, дыхания, нервной регуляции и обмена веществ.",difficulty:"medium",tags:["патогенез"]},{id:"shock-states-004",topicId:"shock-states",question:"К развитию какого состояния приводит недостаточное кровоснабжение жизненно важных органов при шоке?",options:["Полиорганной недостаточности","Гипертонического криза","Хронической анемии","Локального воспаления"],correctIndex:0,explanation:"Недостаточное кровоснабжение жизненно важных органов при шоке приводит к развитию полиорганной недостаточности.",difficulty:"medium",tags:["осложнения","патогенез"]},{id:"shock-states-005",topicId:"shock-states",question:"Что происходит с артериальным давлением при шоковых состояниях?",options:["Остаётся в пределах нормы","Резко повышается","Сначала повышается, затем стабилизируется","Выраженно снижается"],correctIndex:3,explanation:"Одним из общих признаков шоковых состояний является выраженное снижение артериального давления.",difficulty:"easy",tags:["симптомы","признаки"]},{id:"shock-states-006",topicId:"shock-states",question:"Как изменяется пульс при развитии шокового состояния?",options:["Сразу замедляется и остаётся редким","Учащается (тахикардия), а позже ослабевает","Не изменяется на протяжении всего состояния","Становится редким, но напряжённым"],correctIndex:1,explanation:"При шоке пульс учащается (тахикардия), а позже происходит его ослабление.",difficulty:"medium",tags:["симптомы","признаки"]},{id:"shock-states-007",topicId:"shock-states",question:"Какие изменения кожных покровов характерны для шоковых состояний?",options:["Сухая горячая покрасневшая кожа","Желтушность кожи и склер","Холодная бледная кожа, холодный липкий пот","Сыпь и выраженный зуд"],correctIndex:2,explanation:"Для шоковых состояний характерны холодная бледная кожа и холодный липкий пот.",difficulty:"easy",tags:["симптомы","признаки"]},{id:"shock-states-008",topicId:"shock-states",question:"Как изменяется состояние сознания при развитии шока?",options:["Сознание сразу полностью утрачивается","Наблюдается беспокойство, затем угнетение сознания","Сознание остаётся ясным до самого конца","Развивается эйфория, сменяющаяся возбуждением"],correctIndex:1,explanation:"При шоке сначала отмечается беспокойство, затем наступает угнетение сознания, возможна потеря сознания.",difficulty:"medium",tags:["симптомы","признаки"]},{id:"shock-states-009",topicId:"shock-states",question:"Какие субъективные ощущения относятся к общим признакам шоковых состояний?",options:["Чувство жара и прилива крови к лицу","Усиление аппетита и жажда деятельности","Головокружение и потемнение в глазах","Онемение только пальцев рук"],correctIndex:2,explanation:"К общим признакам шоковых состояний относятся головокружение, потемнение в глазах и слабость.",difficulty:"easy",tags:["симптомы","признаки"]},{id:"shock-states-010",topicId:"shock-states",question:"Сколько видов шока выделяется в классификации шоковых состояний?",options:["Пять","Шесть","Семь","Девять"],correctIndex:2,explanation:"Классификация шоковых состояний включает семь видов: гиповолемический, геморрагический, травматический, анафилактический, септический, кардиогенный и комбинированный.",difficulty:"medium",tags:["классификация"]},{id:"shock-states-011",topicId:"shock-states",question:"При каком состоянии возникает гиповолемический шок?",options:["При значительной потере жидкости или плазмы","При попадании бактерий в кровь","При тяжёлом нарушении работы сердца","При аллергической реакции немедленного типа"],correctIndex:0,explanation:"Гиповолемический шок возникает при значительной потере жидкости или плазмы.",difficulty:"easy",tags:["гиповолемический шок","классификация"]},{id:"shock-states-012",topicId:"shock-states",question:"Какие причины приводят к развитию гиповолемического шока?",options:["Инфаркт, аритмии, кардиомиопатии","Обезвоживание, ожоги, рвота, диарея","Укусы насекомых и приём лекарственных препаратов","Системная бактериальная инфекция"],correctIndex:1,explanation:"Причинами гиповолемического шока являются обезвоживание, ожоги, рвота и диарея.",difficulty:"medium",tags:["гиповолемический шок","причины"]},{id:"shock-states-013",topicId:"shock-states",question:"В чём заключается лечение гиповолемического шока?",options:["В назначении наркотических анальгетиков и иммобилизации","В введении антибиотиков широкого спектра действия","В восполнении объёма жидкости растворами натрия хлорида, Рингера и др.","В немедленном переливании цельной крови"],correctIndex:2,explanation:"Лечение гиповолемического шока заключается в восполнении объёма жидкости — применяются растворы NaCl, Рингера и др.",difficulty:"medium",tags:["гиповолемический шок","лечение"]},{id:"shock-states-014",topicId:"shock-states",question:"При каком состоянии развивается геморрагический шок?",options:["При массивной кровопотере","При обширных ожогах","При тяжёлой аллергической реакции","При выраженном болевом синдроме"],correctIndex:0,explanation:"Геморрагический шок развивается при массивной кровопотере.",difficulty:"easy",tags:["геморрагический шок","классификация"]},{id:"shock-states-015",topicId:"shock-states",question:"Что входит в лечение геморрагического шока?",options:["Введение вазопрессоров и сердечных гликозидов","Остановка кровотечения, гемостатические средства, переливание крови и её компонентов","Ингаляционное введение бронхорасширяющих средств","Назначение антибиотиков широкого спектра действия"],correctIndex:1,explanation:"Лечение геморрагического шока включает остановку кровотечения, гемостатические средства, переливание крови и её компонентов.",difficulty:"medium",tags:["геморрагический шок","лечение"]},{id:"shock-states-016",topicId:"shock-states",question:"Какое второе название имеет травматический шок?",options:["Гиповолемический","Комбинированный","Нейрогенный","Болевой"],correctIndex:3,explanation:"Травматический шок также называется болевым, так как возникает при тяжёлых травмах и выраженном болевом синдроме.",difficulty:"easy",tags:["травматический шок","терминология"]},{id:"shock-states-017",topicId:"shock-states",question:"Какая группа препаратов применяется при лечении травматического (болевого) шока?",options:["Наркотические анальгетики","Антигистаминные препараты","Гемостатические средства","Сердечные гликозиды"],correctIndex:0,explanation:"При травматическом (болевом) шоке применяются наркотические анальгетики, а также иммобилизация и инфузии.",difficulty:"medium",tags:["травматический шок","лечение"]},{id:"shock-states-018",topicId:"shock-states",question:"Какое немедикаментозное мероприятие входит в лечение травматического шока наряду с обезболиванием и инфузиями?",options:["Активная лечебная гимнастика","Иммобилизация","Наложение согревающего компресса","Промывание желудка"],correctIndex:1,explanation:"Лечение травматического шока включает наркотические анальгетики, иммобилизацию и инфузии.",difficulty:"medium",tags:["травматический шок","лечение"]},{id:"shock-states-019",topicId:"shock-states",question:"Чем по своей сути является анафилактический шок?",options:["Реакцией на массивную кровопотерю","Следствием системной бактериальной инфекции","Тяжёлой аллергической реакцией немедленного типа","Осложнением нарушения сердечного ритма"],correctIndex:2,explanation:"Анафилактический шок — это тяжёлая аллергическая реакция немедленного типа.",difficulty:"easy",tags:["анафилактический шок","определение"]},{id:"shock-states-020",topicId:"shock-states",question:"Какое действующее вещество является препаратом выбора при анафилактическом шоке?",options:["Адреналин","Дексаметазон","Морфин","Фуросемид"],correctIndex:0,explanation:"При анафилактическом шоке препаратом выбора является адреналин; дополнительно применяются антигистаминные препараты, глюкокортикостероиды и инфузии.",difficulty:"medium",tags:["анафилактический шок","лечение","препараты"]},{id:"shock-states-021",topicId:"shock-states",question:"Какие группы препаратов применяются при анафилактическом шоке наряду с адреналином?",options:["Гемостатические средства и сердечные гликозиды","Наркотические анальгетики и миорелаксанты","Антигистаминные препараты и глюкокортикостероиды","Антибиотики широкого спектра и муколитики"],correctIndex:2,explanation:"При анафилактическом шоке помимо адреналина применяются антигистаминные препараты, глюкокортикостероиды и инфузии.",difficulty:"medium",tags:["анафилактический шок","лечение"]},{id:"shock-states-022",topicId:"shock-states",question:"Чем вызывается септический шок?",options:["Потерей плазмы при обширных ожогах","Попаданием бактерий в кровь и системной инфекцией","Резким выбросом гистамина при контакте с аллергеном","Нарушением сократительной способности миокарда"],correctIndex:1,explanation:"Септический шок вызывается попаданием бактерий в кровь и системной инфекцией.",difficulty:"easy",tags:["септический шок","причины"]},{id:"shock-states-023",topicId:"shock-states",question:"Что является основой лечения септического шока?",options:["Наркотические анальгетики и иммобилизация","Переливание крови и её компонентов","Введение антигистаминных препаратов","Антибиотики широкого спектра, инфузионная терапия, поддержка функций органов"],correctIndex:3,explanation:"Лечение септического шока включает антибиотики широкого спектра действия, инфузионную терапию и поддержку функций органов.",difficulty:"medium",tags:["септический шок","лечение"]},{id:"shock-states-024",topicId:"shock-states",question:"С чем связано развитие кардиогенного шока?",options:["С тяжёлым нарушением работы сердца","С потерей большого объёма плазмы","С реакцией немедленного типа на аллерген","С проникновением инфекции в кровоток"],correctIndex:0,explanation:"Кардиогенный шок связан с тяжёлым нарушением работы сердца.",difficulty:"easy",tags:["кардиогенный шок","определение"]},{id:"shock-states-025",topicId:"shock-states",question:"Какие причины вызывают кардиогенный шок?",options:["Ожоги, рвота, диарея","Инфаркт, аритмии, кардиомиопатии","Укусы насекомых и приём антибиотиков","Массивное наружное кровотечение"],correctIndex:1,explanation:"Причинами кардиогенного шока являются инфаркт, аритмии и кардиомиопатии.",difficulty:"medium",tags:["кардиогенный шок","причины"]},{id:"shock-states-026",topicId:"shock-states",question:"Какие группы препаратов применяются при лечении кардиогенного шока?",options:["Муколитики и противокашлевые средства","Антигистаминные препараты и гемостатики","Вазопрессоры и сердечные гликозиды","Наркотические анальгетики и диуретики"],correctIndex:2,explanation:"При кардиогенном шоке проводится поддержка сердечной деятельности с применением вазопрессоров и сердечных гликозидов.",difficulty:"medium",tags:["кардиогенный шок","лечение"]},{id:"shock-states-027",topicId:"shock-states",question:"При каких условиях развивается комбинированный шок?",options:["При повторном воздействии одного и того же аллергена","При постепенном развитии обезвоживания","При переходе одного вида шока в другой с течением времени","При одновременном действии нескольких повреждающих факторов"],correctIndex:3,explanation:"Комбинированный шок развивается при одновременном действии нескольких факторов, например травма + кровопотеря + инфекция.",difficulty:"medium",tags:["комбинированный шок","классификация"]},{id:"shock-states-028",topicId:"shock-states",question:"Каким должно быть лечение комбинированного шока?",options:["Комплексным, направленным на устранение всех причин","Направленным только на восполнение объёма жидкости","Ограниченным введением наркотических анальгетиков","Основанным исключительно на антибиотикотерапии"],correctIndex:0,explanation:"Лечение комбинированного шока комплексное, направленное на устранение всех причин, вызвавших его развитие.",difficulty:"medium",tags:["комбинированный шок","лечение"]},{id:"shock-states-029",topicId:"shock-states",question:"Какое мероприятие стоит первым в общих принципах лечения шоковых состояний?",options:["Проведение инфузионной терапии","Быстрое устранение причины шока","Восстановление дыхания и оксигенации","Проведение сердечно-лёгочной реанимации"],correctIndex:1,explanation:"Первым принципом лечения шоковых состояний является быстрое устранение причины шока.",difficulty:"medium",tags:["лечение","принципы"]},{id:"shock-states-030",topicId:"shock-states",question:"С какой целью в общих принципах лечения шока проводится инфузионная терапия?",options:["Для снижения температуры тела","Для устранения болевого синдрома","Для обеспечения адекватного объёма циркулирующей крови","Для подавления аллергической реакции"],correctIndex:2,explanation:"Инфузионная терапия проводится для обеспечения адекватного объёма циркулирующей крови.",difficulty:"medium",tags:["лечение","принципы"]}];export{t as default};
